from pathlib import Path
import os
front=Path(os.environ['SRE_ENGINE_ROOT'])/'modern_ui/frontend';app=front/'app.js';s=app.read_text(encoding='utf-8')
prefix="function renderCapitalPlan(d){const s=d.capital_summary||{},buys=d.new_buys||[],lc=s.live_lane_counts||{},blockers=s.top_blockers||{};"
pos=s.find(prefix)
if pos<0:raise RuntimeError('capital summary patch point missing')
cut=s.find(';',pos+len(prefix));old=s[pos:cut+1]
new=r"""function renderCapitalPlan(d){const s=d.capital_summary||{},buys=d.new_buys||[],lc=s.live_lane_counts||{},blockers=s.top_blockers||{},universe=+s.live_universe_size||200;if($('#capitalLiveSummary')){const top=Object.entries(blockers).slice(0,5);$('#apitalLiveSummary').innerHTML=`<div class="capital-live-header"><strong>LIVE_DECISION_V1</strong><span>Momentum BUY ${lc.momentum_buy||0}</span><span>Recovery BUY ${lc.recovery_buy||0}</span><span>Both ${lc.both||0}</span><span>Watch ${lc.watch||0}</span><span>Avoid ${lc.avoid||0}</span><span>No opportunity ${lc.no_opportunity||0}</span></div><div class="capital-zero-note">${buys.length?'Qualified BUY opportunities are available.':'No stocks currently satisfy LIVE_DECISION_V1 BUY requirements. Capital remains in cash rather than forcing a trade.'}</div>${top.length?`<div class="blocker-summary"><b>Why no capital was deployed</b><small>Stocks affected; one stock may appear under more than one reason.</small>${top.map(([code,count])=>`<div class="blocker-row"><span>${escapeHtml(humanReason(code))}</span><strong>${count}</strong><span>${universe?((100*count/universe).toFixed(1)+'%'):'-'}</span></div>`).join('')}</div>`:''}`;}"""
s=s.replace(old,new,1);app.write_text(s,encoding='utf-8')
css=front/'styles.css';c=css.read_text(encoding='utf-8');c+=r"""
.opportunity-detail-v2{font-size:12px;line-height:1.5;max-width:820px;overflow-wrap:anywhere}.decision-summary-grid{display:grid;grid-template-columns:repeat(5,minmax(95px,1fr));gap:8px;margin-bottom:14px}.decision-summary-grid>div,.evidence-grid-v2>div{border:1px solid var(--line2);background:#fafbff;border-radius:10px;padding:10px}.evidence-grid-v2{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:8px;margin:8px 0 16px}.clean-theses p,.diagnostic-details pre{overflow-wrap:anywhere}.diagnostic-details pre{white-space:pre-wrap;word-break:break-word}.capital-live-summary{display:block!important}.capital-live-header{display:flex;flex-wrap:wrap;gap:8px 14px}.capital-zero-note{margin:10px 0;padding:10px 12px;background:#f6f7fb;border-radius:9px}.blocker-summary{margin-top:10px;border-top:1px solid var(--line2);padding-top:10px}.blocker-summary>small{display:block;color:var(--muted);margin:3px 0 8px}.blocker-row{display:grid;grid-template-columns:minmax(260px,1fr) 80px 65px;gap:12px;padding:7px 0;border-top:1px solid var(--line2)}@media(max-width:900px){.decision-summary-grid,.evidence-grid-v2{grid-template-columns:repeat(2,minmax(0,1fr))}.detail-theses.clean-theses{grid-template-columns:1fr}}
""";css.write_text(c,encoding='utf-8')
print('0.14.2 capital UX repair applied')
